+#[test]
+fn exists_as_a_coalesce_arm_and_a_bind_source() {
+    assert_identical(
+        &dataset(),
+        "SELECT ?n ?v WHERE { ?s foaf:name ?n . BIND(EXISTS { ?s ex:tag ?t } AS ?v) } ORDER BY ?n",
+    );
+}
